from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
import os, re, math, statistics
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
print('Saved workbook sheets:', wb.sheetnames)
ws=wb['Task']
errors=[]
# Check populated lookup formulas.
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            L=get_column_letter(c)
            exp=f'=INDEX(Data!$H$21:$L$38, MATCH($D{r}, Data!$D$21:$D$38, 0), MATCH({L}$10, Data!$H$4:$L$4, 0))'
            if ws.cell(r,c).value != exp:
                errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
# Check headroom formulas.
for i,r in enumerate(range(35,41)):
    for c in range(8,13):
        L=get_column_letter(c)
        exp=f'=({L}{12+i}-{L}{19+i})/{L}{26+i}*100'
        if ws.cell(r,c).value != exp:
            errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
# Check stats and weighted formulas.
for c in range(8,13):
    L=get_column_letter(c)
    exps={42:f'=MIN({L}35:{L}40)',43:f'=MAX({L}35:{L}40)',44:f'=MEDIAN({L}35:{L}40)',45:f'=AVERAGE({L}35:{L}40)',46:f'=PERCENTILE({L}35:{L}40, 0.25)',47:f'=PERCENTILE({L}35:{L}40, 0.75)',50:f'=SUMPRODUCT({L}35:{L}40, {L}26:{L}31) / SUM({L}26:{L}31)'}
    for r,exp in exps.items():
        if ws.cell(r,c).value != exp:
            errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
all_formula_cells=[]
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=ws.max_column):
    for cell in row:
        if isinstance(cell.value, str) and cell.value.startswith('='):
            all_formula_cells.append(cell.coordinate)
print('Formula cells on Task:', len(all_formula_cells))
print('Expected newly populated formula cells:', 30*3 + 30 + 30 + 5)
print('Formula validation errors:', len(errors))
if errors:
    for e in errors[:10]: print('ERROR', e)
# Check no dotted percentile names in workbook formulas.
dotted=[]
for wsx in wb.worksheets:
    for row in wsx.iter_rows():
        for cell in row:
            if isinstance(cell.value, str) and 'PERCENTILE.' in cell.value.upper():
                dotted.append((wsx.title, cell.coordinate, cell.value))
print('Dotted percentile formulas:', dotted)
# Manual numeric spot-check from source data.
wdata=wb['Data']
series={wdata.cell(r,4).value: [wdata.cell(r,c).value for c in range(8,13)] for r in range(21,39)}
years=[wdata.cell(4,c).value for c in range(8,13)]
print('Data year headers H4:L4:', years)
# H35 expected = (NCL open - NCL used)/NCL staff * 100
h35=(series['NCL_OPEN_SLOTS'][0]-series['NCL_USED_SLOTS'][0])/series['NCL_STAFF_BEDS'][0]*100
vals=[]
for prefix in ['NCL','SCL','ECL','WCL','CCL','KCL']:
    vals.append((series[f'{prefix}_OPEN_SLOTS'][0]-series[f'{prefix}_USED_SLOTS'][0])/series[f'{prefix}_STAFF_BEDS'][0]*100)
weighted=sum(v*series[f'{p}_STAFF_BEDS'][0] for v,p in zip(vals,['NCL','SCL','ECL','WCL','CCL','KCL']))/sum(series[f'{p}_STAFF_BEDS'][0] for p in ['NCL','SCL','ECL','WCL','CCL','KCL'])
print('Manual H35 expected numeric:', h35)
